const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES),LINES=[109,110,111,112,113,158,159,161,162,163,164,165,166,179,183,184,185,186,187,188,189,202,203,204,205,298,299,300,301,302,306,307,308,309,313,314,315,316,317,318,322,323,324,325,326,327,328,329,330,331,332,333],assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const ls=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<ls.length;i++){const line=ls[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src);assert(p.declarations.length===515&&p.dead.length===52,'parent parse drift');assert(p.dead.map(d=>d.line).join(',')===LINES.join(','),'dead lines drift');assert(new Set(p.dead.map(d=>d.selector)).size===9,'family drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===40&&p.dead.length-identical===12,'winner count drift');const nl=/\r?\n$/.test(src),ls=src.split(/\r?\n/);if(nl&&ls.at(-1)==='')ls.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(ls[d.line-1]?.trim().startsWith(`${d.property}:`),`source mismatch ${d.line}`);ls.splice(d.line-1,1)}fs.writeFileSync(TARGET,ls.join('\n')+(nl?'\n':''));const q=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/),buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');assert(q.declarations.length===463&&q.dead.length===0,'candidate parse drift');assert(stat[0]==='0'&&stat[1]==='52'&&stat[2]===TARGET,'diff drift');assert(hash===HASH&&buf.length===BYTES,`identity drift ${hash}/${buf.length}`);console.log(`PROMOTION BUILD PASS|hash=${hash}|bytes=${buf.length}|files=1|additions=0|deletions=52|decl=515->463|dead=52->0|families=9|identical=40|changed=12`);
